<?php require 'config.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check();$n=trim($_POST['name']??'');$e=strtolower(trim($_POST['email']??''));$pw=$_POST['password']??'';if(strlen($n)<2||strlen($n)>100||!filter_var($e,FILTER_VALIDATE_EMAIL)||strlen($pw)<8)$err='Enter a valid name, email and password of 8+ characters.';else{try{$s=$db->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');$s->execute([$n,$e,password_hash($pw,PASSWORD_DEFAULT)]);go('login.php');}catch(Throwable $ex){$err='Email may already exist.';}}}head('Sign up');?><section class="form"><h1>Create account</h1><p><?=h($err)?></p><form method="post"><input type="hidden" name="token" value="<?=h(token())?>"><label>Name<input name="name" maxlength="100" required></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="8" required></label><button>Sign up</button></form></section><?php foot();?>